private val BG=Color(0xFF070A12); private val CARD=Color(0xFF101725); private val CYAN=Color(0xFF26D9FF); private val PURPLE=Color(0xFF8B5CFF); private val GREEN=Color(0xFF31E59A)
private data class Project(val id:String,val name:String,val date:String,val text:String,val files:Int,val dir:File)

class LauncherActivity:ComponentActivity(){
 override fun onCreate(b:Bundle?){super.onCreate(b);setContent{App()};if(b==null) capture(intent)}
 override fun onNewIntent(i:Intent){super.onNewIntent(i);capture(i)}
 private fun capture(i:Intent?){if(i?.action!=Intent.ACTION_SEND&&i?.action!=Intent.ACTION_SEND_MULTIPLE)return;val text=i.getStringExtra(Intent.EXTRA_TEXT).orEmpty();val uri=i.getParcelableExtra<Uri>(Intent.EXTRA_STREAM);if(text.isNotBlank()||uri!=null)Store.create(this,"Shared AI Chat",text,listOfNotNull(uri))}
}

@Composable private fun App(){val c=LocalContext.current;var tick by remember{mutableIntStateOf(0)};var page by remember{mutableIntStateOf(0)};var picked by remember{mutableStateOf<Project?>(null)};var create by remember{mutableStateOf(false)};var import by remember{mutableStateOf(false)};val projects=remember(tick){Store.list(c)};val picker=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){u->if(u!=null){Store.importZip(c,u);tick++}}
 MaterialTheme(colorScheme=darkColorScheme(background=BG,surface=CARD,primary=CYAN)){Surface(Modifier.fillMaxSize(),color=BG){when{picked!=null->Detail(picked!!,{picked=null});create->Create({create=false},{Store.create(c,it.first,it.second,emptyList());create=false;tick++});import->Import({import=false}){picker.launch(arrayOf("application/zip","application/octet-stream"))};else->Scaffold(containerColor=BG,bottomBar={Nav(page){page=it}}){p->Column(Modifier.fillMaxSize().padding(p)){Header();when(page){0->Home(projects,{create=true},{import=true}){picked=it};1->Projects(projects){picked=it};2->Transfer(projects){picked=it};else->Settings()}}}}}}}}

