private object Store{
 private fun root(c:Context)=File(c.filesDir,"projects").apply{mkdirs()}
 fun list(c:Context)=root(c).listFiles()?.filter{it.isDirectory}.mapNotNull{read(it)}?.sortedByDescending{it.dir.lastModified()}?:emptyList()
 private fun read(d:File)=try{val j=JSONObject(File(d,"metadata.json").readText());Project(j.getString("id"),j.getString("name"),j.getString("date"),File(d,"chat.txt").takeIf{it.exists()}?.readText().orEmpty(),d.resolve("attachments").listFiles()?.size?:0,d)}catch(_:Exception){null}
 fun create(c:Context,name:String,text:String,uris:List<Uri>){val id="p_"+System.currentTimeMillis();val d=File(root(c),id);val a=File(d,"attachments");a.mkdirs();File(d,"chat.txt").writeText(text);uris.forEachIndexed{i,u->try{c.contentResolver.openInputStream(u)?.use{input->FileOutputStream(File(a,"attachment_$i")).use{out->input.copyTo(out)}}}catch(_:Exception){}};val date=SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US).format(Date());File(d,"metadata.json").writeText(JSONObject().put("id",id).put("name",name).put("date",date).toString(2));File(d,"instructions.md").writeText("Continue from this checkpoint. Inspect the supplied chat/context and files. Do not redo completed work.")}
 private fun zip(c:Context,p:Project):File{val f=File(c.cacheDir,p.id+".zip");ZipOutputStream(BufferedOutputStream(FileOutputStream(f))).use{z->p.dir.walkTopDown().filter{it.isFile}.forEach{x->z.putNextEntry(ZipEntry(p.dir.toPath().relativize(x.toPath()).toString()));x.inputStream().use{it.copyTo(z)};z.closeEntry()}};return f}
 fun export(c:Context,p:Project)=shareFile(c,zip(c,p));fun share(c:Context,p:Project)=shareFile(c,zip(c,p))
 private fun shareFile(c:Context,f:File){val u=FileProvider.getUriForFile(c,"com.offtamil.aitaskmanager.files",f);val i=Intent(Intent.ACTION_SEND).apply{type="application/zip";putExtra(Intent.EXTRA_STREAM,u);putExtra(Intent.EXTRA_TEXT,"AI Task checkpoint. Open/restore this ZIP, inspect the included context and files, then continue the task from the checkpoint.");addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)};c.startActivity(Intent.createChooser(i,"Share checkpoint to AI"))}
 fun importZip(c:Context,u:Uri){try{val id="import_"+System.currentTimeMillis();val d=File(root(c),id);d.mkdirs();ZipInputStream(BufferedInputStream(c.contentResolver.openInputStream(u)!!)).use{z->var e=z.nextEntry;while(e!=null){val out=File(d,e.name).canonicalFile;if(!out.path.startsWith(d.canonicalPath+File.separator)){e=z.nextEntry;continue};if(e.isDirectory)out.mkdirs()else{out.parentFile?.mkdirs();FileOutputStream(out).use{z.copyTo(it)}};z.closeEntry();e=z.nextEntry}};if(!File(d,"metadata.json").exists())File(d,"metadata.json").writeText(JSONObject().put("id",id).put("name","Imported Checkpoint").put("date",SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US).format(Date())).toString(2))}catch(_:Exception){}}
}
